function context(record,parent){
 const f=record?.fields??{};const a=f['Review Intent Author'];
 ck(a?.id===ownerIdentity.id&&a?.email===ownerIdentity.email,'Owner-authored intent required');
 const raw=f['Review Intent JSON'];ck(typeof raw==='string'&&raw.length<=8192,'Missing bounded intent');
 const i=JSON.parse(raw);
 const keys=['schemaVersion','action','recordId','parentId','projectId','originalClipId','finalClipId','expectedVersion','reviewGeneration','nonce'];
 ck(i&&Object.keys(i).length===keys.length&&keys.every(k=>Object.hasOwn(i,k)),'Invalid intent schema');
 ck(i.schemaVersion===1&&['refresh-current','approve-current','reject-current'].includes(i.action),'Invalid action');
 ck(/^rec[A-Za-z0-9]+$/.test(i.recordId)&&i.recordId===record.id,'Wrong record');
 ck(Array.isArray(f['Parent Content'])&&f['Parent Content'].length===1&&f['Parent Content'][0]===i.parentId&&parent?.id===i.parentId,'Wrong parent');
 ck(/^P[A-Za-z0-9]+$/.test(i.projectId)&&parent.fields?.['OpusClip Short Project ID']===i.projectId,'Wrong project');
 ck(/^[A-Za-z0-9]+$/.test(i.originalClipId)&&/^[A-Za-z0-9]+$/.test(i.finalClipId)&&f['OpusClip Clip ID']===i.projectId+'.'+i.originalClipId,'Wrong original identity');
 ck(Number.isSafeInteger(i.expectedVersion)&&i.expectedVersion>=0,'Invalid version');
 ck(i.reviewGeneration===null||typeof i.reviewGeneration==='string'&&i.reviewGeneration.length<=128,'Invalid generation');
 ck(typeof i.nonce==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i.test(i.nonce),'Invalid nonce');
 return {i,raw,author:a};
}
function freshMedia(ctx,raw){
 const d=raw?.data??raw,c=Array.isArray(d)?(d.length===1?d[0]:null):d,i=ctx.i;
 ck(c?.id===i.projectId+'.'+i.finalClipId&&c.projectId===i.projectId,'Wrong rendered clip');
 ck(c.renderAsVideoFile?.pending===false,'Render readiness unconfirmed');
 ck(typeof c.text==='string'&&c.text.trim(),'Missing current transcript');
 const u=c.uriForExport;
 ck(typeof u==='string'&&u.length<=16384&&!/[\s\\#]/.test(u),'Invalid media URL');
 const m=/^https:\/\/signed-ext\.cdn\.opus\.pro(\/[^?]*)(?:\?[^#]*)?$/.exec(u);
 ck(m&&m[1].includes('/'+i.projectId+'/c.'+i.finalClipId+'/')&&!m[1].split('/').some(x=>x==='.'||x==='..'),'Wrong media origin/path');
 return {clipId:i.finalClipId,reviewGeneration:i.nonce,renderReady:true,url:u,transcript:c.text};
}
function mirrorFields(c){return {'flddpK92veotSNWxV':c.final.url,'fldL2TMrJ9rnwXltx':c.final.transcript,'fldYjoD70SRrSlBox':c.status,'fldG9gklzS07bEbrz':JSON.stringify(c)};}
function commitRequest({row,owner,initial,record,parent,media}){
 const current=context(record,parent);ck(current.raw===initial.raw,'Intent changed during processing');
 const {s,r}=readLocked(row,owner),i=current.i,key='review|'+i.recordId+'|'+i.nonce,prior=s.receipts[key];
 if(prior){ck(prior.intent===current.raw,'Nonce reused');const latest=s.clips[i.recordId];ck(latest?.final&&latest.id===i.recordId,'Canonical replay state missing');return {action:prior.state==='completed'?'repair-mirrors':'reconcile',receipt:prior,fields:mirrorFields(latest)};}
 // Must be verified against the scoped live scheduler before registering real managed clips.
 ck(s.currentRenderSchedulerGuardVerified===true,'Current-render scheduler guard not installed');
 const c=s.clips[i.recordId];
 ck((c?.version??0)===i.expectedVersion,'Version changed');
 ck(!c||(c.mode==='current-render-v1'&&c.parentId===i.parentId&&c.projectId===i.projectId&&c.originalClipId===i.originalClipId),'Canonical lineage changed');
 ck((c?.final?.reviewGeneration??null)===i.reviewGeneration,'Preview changed');
 ck(!Object.values(s.receipts).some(x=>x.recordId===i.recordId&&x.state!=='completed'),'Unresolved receipt');
 let n=clone(s),registry=clone(r);
 if(i.action==='refresh-current'){
  ck(media?.clipId===i.finalClipId&&media.reviewGeneration===i.nonce&&media.renderReady,'Missing exact media');
  n.generation++;n.clips[i.recordId]={id:i.recordId,parentId:i.parentId,projectId:i.projectId,originalClipId:i.originalClipId,mode:'current-render-v1',version:i.expectedVersion+1,status:'Needs Review',final:media};
  if(!registry.clipIds.includes(i.recordId))registry.clipIds.push(i.recordId);
 }else{
  ck(c&&c.final?.clipId===i.finalClipId,'Selected copy changed');
  if(i.action==='approve-current')n=JSON.parse(approveCurrent({row,owner,recordId:i.recordId,expectedVersion:i.expectedVersion,reviewGeneration:i.reviewGeneration,persistedAuthor:current.author,verifiedOwner:ownerIdentity}).reviewLedger);
  else{n.generation++;n.clips[i.recordId]={...c,version:c.version+1,status:'Rejected',approval:null};}
 }
 const final=n.clips[i.recordId];
 const fields=mirrorFields(final);
 n.receipts[key]={state:'completed',recordId:i.recordId,intent:current.raw,fields};
 return {action:'persist-canonical-first',expectedGeneration:s.generation,reviewLedger:JSON.stringify(n),managedClips:JSON.stringify(registry),fields,receiptKey:key};
}
const id=$input.first().json.body?.recordId;if(typeof id!=='string'||!/^rec[A-Za-z0-9]+$/.test(id))throw Error('Invalid wake');return [{json:{recordId:id}}];

